using IptvManagement.Application.Abstractions; using IptvManagement.Application.DTOs; using IptvManagement.Application.Common; using IptvManagement.Domain.Enums; using IptvManagement.Domain.Exceptions; using IptvManagement.Infrastructure.Data; using Microsoft.EntityFrameworkCore;
namespace IptvManagement.Infrastructure.Services;
public class SubscriptionService(AppDbContext db,ITokenService tokens):ISubscriptionService{ public async Task<TokenIssueResult> IssuePlaylistTokenAsync(Guid id,CancellationToken ct){ var s=await db.Subscriptions.FindAsync([id],ct)??throw new NotFoundException("Abonnement wurde nicht gefunden."); var token=tokens.CreateSecureToken(); s.PlaylistTokenHash=tokens.HashToken(token); s.TokenCreatedAtUtc=DateTime.UtcNow; db.AuditLogs.Add(new(){Action="Playlist-Token erstellt",EntityName="Subscription",EntityId=id.ToString()}); await db.SaveChangesAsync(ct); return new(token,s.TokenCreatedAtUtc.Value); } public async Task RenewAsync(Guid id,int months,string? userId,CancellationToken ct){ var s=await db.Subscriptions.FindAsync([id],ct)??throw new NotFoundException("Abonnement wurde nicht gefunden."); s.Renew(months,DateTime.UtcNow); db.AuditLogs.Add(new(){UserId=userId,Action=$"Abonnement um {months} Monate verlängert",EntityName="Subscription",EntityId=id.ToString()}); await db.SaveChangesAsync(ct); } public async Task RevokePlaylistTokenAsync(Guid id,CancellationToken ct){ var s=await db.Subscriptions.FindAsync([id],ct)??throw new NotFoundException("Abonnement wurde nicht gefunden."); s.PlaylistTokenHash=null; db.AuditLogs.Add(new(){Action="Playlist-Token widerrufen",EntityName="Subscription",EntityId=id.ToString()}); await db.SaveChangesAsync(ct); } }
public class InvoiceService(AppDbContext db):IInvoiceService{ public async Task<InvoiceDto> CreateAsync(Guid customerId,Guid subscriptionId,decimal netAmount,CancellationToken ct){ var taxRate=decimal.Parse((await db.SystemSettings.FirstOrDefaultAsync(x=>x.Key=="Tax:VatRate",ct))?.Value??"20"); var tax=Math.Round(netAmount*taxRate/100,2); var invoice=new Domain.Entities.Invoice{CustomerId=customerId,SubscriptionId=subscriptionId,InvoiceNumber=$"RE-{DateTime.UtcNow:yyyyMMdd}-{await db.Invoices.CountAsync(ct)+1:0000}",InvoiceDateUtc=DateTime.UtcNow,DueDateUtc=DateTime.UtcNow.AddDays(14),NetAmount=netAmount,TaxAmount=tax,GrossAmount=netAmount+tax,Currency="EUR",Status=InvoiceStatus.Issued}; db.Invoices.Add(invoice); await db.SaveChangesAsync(ct); return new(invoice.Id,invoice.CustomerId,invoice.SubscriptionId,invoice.InvoiceNumber,invoice.InvoiceDateUtc,invoice.DueDateUtc,invoice.NetAmount,invoice.TaxAmount,invoice.GrossAmount,invoice.Currency,invoice.Status,invoice.PdfFilePath); } public byte[] RenderPdf(InvoiceDto i)=>System.Text.Encoding.UTF8.GetBytes($"Rechnung {i.InvoiceNumber}
Netto {i.NetAmount:n2} {i.Currency}
USt {i.TaxAmount:n2}
Brutto {i.GrossAmount:n2}"); }
public class DashboardService(AppDbContext db):IDashboardService{ public async Task<DashboardDto> GetAsync(CancellationToken ct){ var now=DateTime.UtcNow; var monthStart=new DateTime(now.Year,now.Month,1,0,0,0,DateTimeKind.Utc); var subs7=await db.Subscriptions.Where(s=>s.ExpirationDateUtc<=now.AddDays(7)&&s.ExpirationDateUtc>now).Take(20).Select(s=>new SubscriptionDto(s.Id,s.CustomerId,s.PackageId,s.SubscriptionNumber,s.StartDateUtc,s.ExpirationDateUtc,s.Status,s.MaxDevices,s.AutomaticRenewal)).ToListAsync(ct); var subs30=await db.Subscriptions.Where(s=>s.ExpirationDateUtc<=now.AddDays(30)&&s.ExpirationDateUtc>now).Take(20).Select(s=>new SubscriptionDto(s.Id,s.CustomerId,s.PackageId,s.SubscriptionNumber,s.StartDateUtc,s.ExpirationDateUtc,s.Status,s.MaxDevices,s.AutomaticRenewal)).ToListAsync(ct); var payments=await db.Payments.OrderByDescending(p=>p.PaymentDateUtc).Take(10).Select(p=>new PaymentDto(p.Id,p.CustomerId,p.SubscriptionId,p.PaymentNumber,p.Amount,p.Currency,p.PaymentMethod,p.PaymentDateUtc,p.Status,p.Reference)).ToListAsync(ct); var audits=await db.AuditLogs.OrderByDescending(a=>a.CreatedAtUtc).Take(20).Select(a=>new AuditLogDto(a.Id,a.UserId,a.Action,a.EntityName,a.EntityId,a.IpAddress,a.CreatedAtUtc)).ToListAsync(ct); return new(await db.Customers.CountAsync(ct),await db.Customers.CountAsync(c=>c.IsActive,ct),await db.Customers.CountAsync(c=>c.IsBlocked,ct),await db.Subscriptions.CountAsync(s=>s.Status==SubscriptionStatus.Active&&s.ExpirationDateUtc>now,ct),await db.Subscriptions.CountAsync(s=>s.ExpirationDateUtc<=now.AddDays(30)&&s.ExpirationDateUtc>now,ct),await db.Subscriptions.CountAsync(s=>s.ExpirationDateUtc<=now,ct),await db.Payments.Where(p=>p.Status==PaymentStatus.Paid&&p.PaymentDateUtc>=monthStart).SumAsync(p=>p.Amount,ct),await db.Payments.Where(p=>p.Status==PaymentStatus.Open).SumAsync(p=>p.Amount,ct),await db.Devices.CountAsync(d=>d.IsActive,ct),await db.Devices.CountAsync(d=>d.IsBlocked,ct),await db.Channels.CountAsync(c=>c.IsActive,ct),subs7,subs30,payments,audits,new decimal[12]); }}
